import { getTalks } from "@/lib/db";
import { TalkList } from "@/components/talk-list";
import { useEffect, useState } from "react";
import type { Talk } from "@/lib/types";

export default function Home() {
  const [talks, setTalks] = useState<Talk[]>([]);
  const [sortByVotes, setSortByVotes] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    getTalks().then((data) => {
      setTalks(data);
      setIsLoading(false);
    });
  }, []);

  const sortedTalks = [...talks].sort((a, b) => {
    if (sortByVotes) {
      return b.votes - a.votes;
    }
    return a.title.localeCompare(b.title);
  });

  return (
    <main>
      <h1 className="mb-4 text-2xl font-bold">Talks</h1>
      <button
        onClick={() => setSortByVotes(!sortByVotes)}
        className="mb-4 px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700"
      >
        {sortByVotes ? "Sort by title" : "Sort by votes"}
      </button>
      {!isLoading && <TalkList talks={sortedTalks} />}
    </main>
  );
}
